'use strict';

/**
* Return a kernel for applying a one-dimensional strided array function to an input ndarray according to a callback function using loop blocking.
*
* @module @stdlib/ndarray/base/kernels/generic/nullary-strided1d-by/blocked
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
* var zeros = require( '@stdlib/array/base/zeros' );
* var gfillBy = require( '@stdlib/blas/ext/base/ndarray/gfill-by' );
* var strategy = require( '@stdlib/ndarray/base/kernels/generic/nullary-strided1d-by/strategy' );
* var kernel = require( '@stdlib/ndarray/base/kernels/generic/nullary-strided1d-by/blocked' );
*
* function clbk( value, idx ) {
*     return ( idx[ 1 ]*100 ) + ( idx[ 2 ]*10 ) + idx[ 3 ];
* }
*
* // Create a data buffer:
* var xbuf = new Float64Array( 12 );
*
* // Define the array shape:
* var xsh = [ 1, 3, 2, 2 ];
*
* // Define the array strides:
* var sx = [ 12, 4, 2, 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray descriptor:
* var x = {
*     'dtype': 'float64',
*     'data': xbuf,
*     'shape': xsh,
*     'strides': sx,
*     'offset': ox,
*     'order': 'row-major'
* };
*
* // Create an ndarray descriptor for the starting index (inclusive):
* var start = {
*     'dtype': 'float64',
*     'data': new Float64Array( [ 0.0 ] ),
*     'shape': [ 1, 3 ],
*     'strides': [ 0, 0 ],
*     'offset': 0,
*     'order': 'row-major'
* };
*
* // Create an ndarray descriptor for the ending index (exclusive):
* var end = {
*     'dtype': 'float64',
*     'data': new Float64Array( [ 4.0 ] ),
*     'shape': [ 1, 3 ],
*     'strides': [ 0, 0 ],
*     'offset': 0,
*     'order': 'row-major'
* };
*
* // Initialize ndarray descriptors representing subarray views:
* var views = [
*     {
*         'dtype': x.dtype,
*         'data': x.data,
*         'shape': [ 2, 2 ],
*         'strides': [ 2, 1 ],
*         'offset': x.offset,
*         'order': x.order
*     },
*     {
*         'dtype': start.dtype,
*         'data': start.data,
*         'shape': [],
*         'strides': [ 0 ],
*         'offset': start.offset,
*         'order': start.order
*     },
*     {
*         'dtype': end.dtype,
*         'data': end.data,
*         'shape': [],
*         'strides': [ 0 ],
*         'offset': end.offset,
*         'order': end.order
*     }
* ];
*
* // Resolve an input strategy when iterating over subarray views:
* var strategyX = strategy( views[ 0 ] );
*
* // Create a workspace array for storing iteration indices:
* var ibuf = zeros( xsh.length );
*
* // Define the loop and core dimensions:
* var ldims = [ 0, 1 ];
* var cdims = [ 2, 3 ];
*
* // Resolve a kernel:
* var f = kernel( 2 );
*
* // Apply strided function:
* f( gfillBy, [ x, start, end ], x, views, [ 1, 3 ], [ 12, 4 ], strategyX, ibuf, ldims, cdims, {}, false, clbk, {} );
*
* var arr = ndarray2array( x.data, x.shape, x.strides, x.offset, x.order );
* // returns [ [ [ [ 0.0, 1.0 ], [ 10.0, 11.0 ] ], [ [ 100.0, 101.0 ], [ 110.0, 111.0 ] ], [ [ 200.0, 201.0 ], [ 210.0, 211.0 ] ] ] ]
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var kernel2d = require( './2d.js' );
var kernel3d = require( './3d.js' );
var main = require( './main.js' );


// MAIN //

setReadOnly( main, 'kernel2d', kernel2d );
setReadOnly( main, 'kernel3d', kernel3d );


// EXPORTS //

module.exports = main;
